const conversationHistory = $node["Prepare Conversation"]["json"]["conversationHistory"];
const userMessage = $node["Prepare Conversation"]["json"]["userMessage"];
const context = $json.matches.map(m => m.metadata.text).join("\n\n");

// Append current user message to history
conversationHistory.push({ role: "user", content: userMessage });

// Limit history to last 3 turns (user + bot)
const recentHistory = conversationHistory.slice(-6); // 3 user messages + 3 bot responses

let historyString = "";
for (const turn of recentHistory) {
  historyString += `${turn.role}: ${turn.content}\n`;
}

const prompt = `You are Solvia, a friendly and supportive workplace wellness assistant. Your tone is warm, encouraging, and empathetic.

**IMPORTANT: Your responses MUST be interactive and use emojis. Do NOT use numbered lists, bullet points, or any Markdown formatting like asterisks, underscores, or hashes.**

Here is the recent conversation history:
${historyString}

Based on the following context and conversation history, answer the user's question.

Context:
${context}

Question: ${userMessage}
`;

return { prompt, conversationHistory };
